    'g.atc_note': 'One square per achievement, held where it was taken. Arma Tactics is the only turn-based thing with Arma on the box, and the board is the closest its data gets to a picture.',
    'g.b_gta_iii': 'GTA III is from 2001 and publishes nothing: no stats, no achievement set. It is the game that turned the series into what it is, and Steam knows how long it was open and not one thing more.',
