    'g.csz_note': 'Condition Zero shipped a single-player campaign nobody remembers and a stat system nobody wired up. Every box on this sheet is unticked because Steam was never handed a single figure from it.',
    'g.csd_cap': 'Eight frames. One of them survived the edit, and it is the clock.',
    'g.csn_kicker': 'counter-strike nexon · the one with the zombies · {h} h',
    'g.csn_note': '{n} of {total} still standing. One mark per achievement, laid down when it falls.',
    'g.b_half_life': 'Half-Life is from 1998. Steam did not exist, and would not for another five years - Valve built it partly to patch this game. There is nothing to read here but the clock, and the HEV suit is the right frame for that, because it is the only readout this game ever gave anybody.',
    'g.b_cs_16': 'Counter-Strike 1.6 has no stat block and no achievements. It was a mod that became the most played game in the world for a decade, and the platform it helped build has one number about it.',
    'g.b_cs_cz': 'Condition Zero was the retail Counter-Strike with a single-player campaign attached. Steam has no stats and no achievements for it - the tour of duty happened entirely off the record.',
    'g.b_cs_cz_ds': 'Deleted Scenes is the campaign that was cut out of Condition Zero and shipped anyway, as its own app. It publishes nothing, which is almost too neat.',
    'g.sk_kicker': 'the elder scrolls v: skyrim  ·  {h} h',
    'g.sk_stars': (v) => `${v.n} ${plural(v.raw, ['star', 'stars'])}`,
    'g.sk_note': 'One constellation per year rather than one chain across the whole save: Steam dates every unlock, and a year is a thing that actually happened. {n} of them are up there, and the brighter a star is the fewer accounts hold it.',
    'g.sk_note_undated': 'One constellation per year rather than one chain across the whole save: Steam dates every unlock, and a year is a thing that actually happened. {n} of them are up there. {u} unlocks came back without a date and are not in the sky - Steam does not always keep one.',
    /* ── Tamriel. Eleven games, and three different kinds of silence ── */
    'g.tes_arena_kicker': 'Arena · 1994 · the whole continent',
    'g.tes_arena_h': 'the nine provinces',
    'g.tes_arena_note': 'Arena is the only game in the series set across all of Tamriel; every one since has picked a single province and stayed there. Not one of these plates has anything on it - the game is from 1994 and Steam has no stat block and no achievement set for it, so the map is the only thing left to draw.',
    'g.tes_dgf_km': 'square kilometres Bethesda generated in 1996 - roughly Great Britain, and still the largest map anybody has shipped',
    'g.tes_dgf_known': 'what Steam knows about it',
    'g.tes_bsp_kicker': 'Battlespire · 1997 · seven levels down',
    'g.tes_bsp_note': 'Not a province and not an open world: a tower standing between Mundus and Oblivion, descended one level at a time. Steam was told none of them.',
    'g.tes_rdg_log': 'the log of Stros M’Kai',
    'g.tes_mrw_kicker': 'Morrowind · 2002 · the prophecy',
    'g.tes_mrw_note': 'Seven verses, and the game spends forty hours asking whether they mean you. All seven are blank here: Morrowind is from 2002 and predates Steam achievements existing at all.',
    'g.tes_obl_kicker': 'Oblivion · 2006 · the hours went in, nothing came back out',
    'g.tes_oblr_kicker': 'the remaster · {h} h',
    'g.tes_oblr_compass': 'the compass, at {pct}% of the set',
    'g.tes_oblr_journal': 'the journal',
    'g.tes_sky11_kicker': 'Skyrim · the 2011 release · {h} h',
    'g.tes_sky11_note': 'One glyph per achievement, lit where the word was learned. {n} are still unread. The Special Edition has the same seventy-five and its own page - this is the wall, that one is the sky.',
    'g.tes_svr_kicker': 'Skyrim · the third time · {h} h',
    'g.tes_svr_sub': 'The same seventy-five achievements as the other two Skyrims, because it is the same game a third time. There is no new data to draw and pretending otherwise would be inventing it - so the page is about the one thing that did change, which is that the spells are now in your hands.',
    'g.tes_svr_left': 'left hand',
    'g.tes_svr_right': 'right hand',
    'g.tes_eso_kicker': 'The Elder Scrolls Online · counted elsewhere',
    'g.tes_eso_ad': 'Aldmeri Dominion',
    'g.tes_eso_dc': 'Daggerfall Covenant',
    'g.tes_eso_ep': 'Ebonheart Pact',
    'g.tes_eso_note': 'This silence is not Morrowind’s. ESO counts more than anything else in the series - thousands of achievements, every dungeon, every zone - and keeps all of it on ZeniMax’s own servers, where this API cannot reach. The banners hang empty because the record is somewhere else, not because there is none.',
    'g.b_tes_arena': 'Arena came out in 1994, a decade before Steam and fifteen years before it had achievements. There is no stat block and no achievement set - not an empty one, none at all. What is here is the clock and a map of the nine provinces this game is the only one to visit.',
    'g.b_tes_daggerfall': 'Daggerfall generated about 161,600 km² - roughly the size of Great Britain, and thirty years later still the largest map anybody has shipped. Steam knows one number about it, and that number is how long it was open. The two figures on this page are the whole story of what a 1996 game reports.',
    'g.b_tes_battlespire': 'A spin-off, a dungeon crawl, and the least played thing with Elder Scrolls on the box. It publishes nothing, which for a game that came out in 1997 is simply what publishing nothing looked like.',
    'g.b_tes_redguard': 'The odd one out twice over: an action-adventure rather than an RPG, and the only one where you play a named person on one small island. Steam has no stats and no achievements for it, so the chart holds the only figure there is.',
    'g.b_morrowind': 'Morrowind is from 2002 and predates Steam achievements existing. It is not a set nobody opened - there is no set. The scroll is blank for the same reason the clock is the only number on this page.',
    'g.b_oblivion': 'The 2006 release publishes nothing: no stats, no achievement set. The remaster released nineteen years later publishes sixty achievements and has a page of its own. Same game, same story, two completely different amounts of evidence.',
    'g.b_eso': 'ESO has thousands of achievements and this API can see none of them: they live on ZeniMax’s servers rather than Steam’s. The hours are real and everything else about this account is being counted somewhere no reader can get to.',
    'g.repo_clock': 'hours of carrying things down stairs. That is the entire report - all of it, the whole thing.',
