    'g.st_war_note': 'Clear Sky is the one game in the series where the factions fight over the Zone whether you are in it or not. None of that was ever wired to Steam: there is no stat block here and no achievement set, so every line of this board is blank. The empty board is the record.',
    'g.st_det_kicker': 'pointed at this game, the detector finds one number',
