    'g.st2_stopped': 'stopped',
    'g.st2_progress_note': 'These five counters all have an achievement hanging off them. Two are plain tallies. The other three state in their own label the number they are counting towards - 50 enemies, 20 kills, a million coupons - and they freeze there, so they are drawn against that number rather than presented as totals. A bar sitting full means the counter stopped, not that the count did.',
    'g.st_ee_kicker': 'the Enhanced Edition · {h} h',
    'g.st_case_note': 'One container per achievement, lit where it holds something. {n} of them are empty, and that is what this page is about.',
    'g.st_swamp_note': 'The Great Swamp, where this game opens and where nothing else in the series goes. {n} stashes pinned on it, in the order they were found.',
    'g.st_cop_note': 'Call of Pripyat is three maps and never lets you forget which one you are standing on. The unlocks are dealt across them in the order they came - this is the closest this game gets to saying how far somebody got.',
    'g.st_cop_empty': 'nothing this far in',
    'g.in_order': 'in the order they came',
    'g.no_date': 'no date',
    'g.h_short': 'h',
    /* The line each of these pages gets to say for itself. */
    'g.b_stalker_soc': 'Shadow of Chernobyl shipped in 2007, before Steam had achievements or a stat block to offer it. So there is nothing here to read but the clock - not a set nobody opened, not a counter at zero: nothing at all. The PDA is the right frame for that, because it is the screen this game hands you when it has one number to give.',
    'g.b_stalker_cs': 'Clear Sky came a year later and publishes exactly as much: nothing. No achievements, no stats. The faction war it invented - the one thing this game has that the other two do not - was never reported anywhere a reader could see it.',
    'g.b_stalker_cop': 'Call of Pripyat closed the trilogy in 2009 and, like both games before it, told Steam only how long it was open. The Enhanced Edition released fifteen years later does publish an achievement set; this, the original, does not.',
    'g.b_repo': 'R.E.P.O. publishes nothing. Not an achievement set with none unlocked - no set at all, and no stats either. A game whose whole loop is four idiots carrying a vase down a staircase while screaming tells Steam one number, and the number is how long the shift was. Everything above is what the rest of the report looks like.',
