    'g.y0d_track': 'track',
    'g.y0d_stage_h': 'the lyrics, one line per unlock',
    'g.y0d_note': 'This is Yakuza 0 again, re-released, and it sits on this profile beside the original. Both are counted because both were launched - but these are not the same hours twice. It gets the karaoke booth rather than Kamurocho a second time, because the city already has a page.',
    'g.whole_days': 'whole days',
    'g.b_kicker': '{name}  ·  nothing but the clock',
    'g.b_set': 'the {n} that exist',
    'g.b_set_note': 'All {n} are still closed. Steam publishes the set for this game, so its size is real - and an empty grid says that better than a sentence does.',
    'g.b_nothing': 'Steam publishes no statistics and no achievements for this game, so the hours are the entire record. That is not a gap in this page; it is the finding.',
    'g.b_offline_tag': 'servers offline',
    'g.b_readout_title': 'The clock, and nothing behind it',
    'g.b_readout_unit': 'hours on the odometer',
    'g.b_screen_hours': '{name}  ·  {h} h  ·  #{rank} in the library. Steam publishes nothing else about it.',
    'g.b_trove': 'Trove publishes nineteen achievements and this profile opened none of them, across forty-six hours. A free voxel MMO tracks almost everything on its own servers and hands Steam none of it.',
    'g.b_beamng': 'BeamNG is a physics sandbox, and a sandbox has no objectives to count. Five achievements exist, none of them unlocked - which for this kind of game is closer to normal than to strange.',
    'g.b_shapez_2': 'Eighty-three achievements published and none opened. shapez 2 was still in early access for most of these hours, and its predecessor - also on this list - is the one that got the unlocks.',
    'g.b_planetary_annihilation': 'A real-time strategy game about blowing up whole planets, and the record of it is nineteen unopened achievements and a number of hours.',
    'g.b_ace_of_words': 'Eighteen achievements, none of them opened. A word game that kept its own score and told Steam none of it.',
    'g.b_alter_world': 'Twelve achievements, none opened, and fewer than a hundred people have ever written a review of it. Some games in a hundred-game library are here because they were in a bundle.',
    'g.b_nyctophobia': 'A game about being afraid of the dark, and the page is kept dark because there is nothing here to light. Eleven achievements exist and none were reached.',
    'g.b_lowglow': 'A minimal puzzle game with twelve achievements and no unlocks. The palette is the one thing it and this page agree on.',
    'g.b_on_a_roll_3d': 'Twenty-four achievements and none of them opened, over twelve and a half hours of rolling a ball down a track.',
    'g.b_make_it_indie': 'A game about making games, which shipped with nine achievements. None were earned, which is a joke the game would probably appreciate.',
    'g.b_rhinos_rage': 'Forty-three achievements, none opened. That is the largest untouched set on this half of the list.',
    'g.b_woodle_tree': 'Eight achievements and no unlocks. A small platformer, and this is the whole of what Steam knows about it.',
    'g.b_apb': 'Sixty achievements published and not one opened, across twelve hours in San Paro. APB keeps its criminal record on its own servers and shares none of it.',
    'g.b_dsx': 'DSX is not a game. It is the driver that makes a DualSense controller work on Windows, and its hours are hours the machine was on, not hours anyone played. It is counted here because Steam counts it - the same argument that keeps Wallpaper Engine out of the ranking would take this out too.',
    'g.b_ghost_recon_phantoms': 'Ubisoft shut this down on 1 December 2016. It was online-only, so there is no version of it left to open - these forty-two hours are not a partial record that could still grow. They are the final one.',
    'g.b_ring_of_elysium': 'Tencent took the servers down. It was a battle royale and nothing else, so the game is simply gone; what is on this page is all there will ever be of it.',
    'g.b_deadbreed': 'A MOBA that closed almost unnoticed. Sixteen hours went into it while it existed, and there is now nothing to compare them against.',
    'g.b_spore': 'Spore has no Steam achievements and no stat block at all - it predates both being normal. Forty-six hours, and the only trace of them is the clock.',
    'g.b_neverwinter': 'A free MMO that keeps every character sheet on its own servers. Steam is told the hours and nothing else, which for this genre is the rule rather than the exception.',
    'g.b_stronghold_kingdoms': 'A persistent-world castle game with no Steam achievements at all. Twenty-six hours, and the keep they built is not something this page can reach.',
    'g.bc2_kicker': 'Battlefield: Bad Company 2  ·  DICE, 2 March 2010',
    'g.bc2_tag_rank': 'library',
    'g.bc2_tag_last': 'last launched',
    'g.bc2_kept_h': 'what was counted, and by whom',
    'g.bc2_kept_game': 'stat attributes the game itself kept on every player - per weapon, per vehicle, per class, plus up to a thousand dog tags taken off people you knifed',
    'g.bc2_kept_steam': 'stats and achievements Steam holds for this game. It never held any. Everything above lived on EA\u2019s servers, and Steam was only ever told the clock',
    'g.bc2_kept_note': 'So this page is not thin because nothing happened. It is thin because the thing that was counting was somewhere else, and the number Steam was trusted with is the one you are looking at.',
    'g.bc2_shutdown_tag': 'online services discontinued',
    'g.bc2_shutdown_date': '8 December 2023',
    'g.bc2_shutdown_body': 'EA switched off the online services for Bad Company 2 that day, thirteen years after release and months after it was delisted. The rank, the unlocks and the dog tags were on those servers. They did not go stale - they went off.',
    'g.bc2_archive': 'Not all of it was lost: an archivist pulled 36.6 billion data points for 15.6 million players out before the lights went off, including 742.3 million dog tag records. It is simply not here, because this site reads Steam and Steam was never given any of it. On PC the multiplayer itself still runs, on community servers rather than EA\u2019s.',
    'g.b_deadlock': 'Valve\u2019s unreleased one. There are no achievements because there is no release - these nineteen hours are of something that does not officially exist yet.',
    'g.b_x_blades': 'Seventeen hours, no achievements, no statistics. A 2009 action game that arrived before either was expected of it.',
    'g.b_endorlight': 'A very small roguelike with no achievements and no statistics. Thirteen hours is more than most of its owners have given it.',
    'g.b_dota_underlords': 'Valve shipped it, then stopped updating it, and it never had Steam achievements. Twelve hours of an auto-battler, and the board it was played on is not something Steam kept.',
    'g.b_two_worlds': 'A 2007 RPG with no Steam achievement set. Eleven hours, and this page can say when they ended and nothing about what happened in them.',
    'g.b_ets1': 'The first Euro Truck Simulator, from 2008, with no achievements and no stat block. Its sequel has both, and a page built out of motorway signage; this one gets the odometer, which is all it can honestly fill.',
    'g.b_street_racing_syndicate': 'From 2004, and it has no Steam achievements at all. Twelve hours of an underground racer, recorded as a number and nothing more.',
    'g.b_vtol_vr': 'A cockpit sim with no Steam achievement set. Every instrument in it reads out something, and none of those readings leave the headset.',
    'g.b_contractors_vr': 'A VR shooter that publishes no achievements and no statistics. Ten hours, and the only instrument left is the clock.',
    'g.b_project_zomboid': 'This is how you died.',
