    'land.rail_body': '<b>157 games</b> have one built out of that game\'s own interface: the post-match scoreboard for Dota 2, the buy menu for Counter-Strike, motorway signage for Euro Truck Simulator. Everything else gets the generic page, which is still the whole record - achievements by rarity, who is playing right now, reviews, news and what it costs today.',
