    'msg.lede': 'Write it here. I read everything. Whatever I accept becomes an item on the board beside this, with the state it is in - and anyone who agrees can vote, so I know what matters most. <b>No account needed.</b>',
    'msg.meta': 'Found a bug, have an idea, or want to complain about something on steamprofiler.org? Send it here. Whatever I accept goes on the public board.',
