    'sup.address': 'address',
    'sup.btc': 'No middleman and no fee from me. Check the address before sending.',
    'sup.btc_ok': 'checksum verified on the server',
    'sup.copy': 'Copy',
    'sup.eyebrow': 'support',
    'sup.failed': 'Could not load the support channels right now.',
    'sup.h1': 'This runs in my house.',
    'sup.honest': 'what I do with it',
    'sup.honest_1': 'None of this is a subscription and there is no supporter tier: people who give and people who do not see exactly the same site, with the same features. I am not locking anything behind a payment.',
    'sup.honest_2': 'If any money shows up, it goes to the server\'s power bill and to a domain that comes out of my pocket today. If a lot shows up, then I think about moving this out of my house and onto something that does not go down when the neighbourhood loses power.',
    'sup.honest_3': 'Rather help without spending? <a href="/feedback">Send a message</a> with a bug or an idea - that is worth the same to me.',
    'sup.kofi': 'Card, once or every month. They take a cut.',
    'sup.lede': 'The site is free, has no ads, no cookies, no trackers and sells nothing - <a href="/privacy">the privacy page says exactly what that means</a>. It runs on a server here at home, on my electricity and my Steam key. <b>If it was useful to you</b> and you want to throw a coin, this is where - and if you do not, use it just the same.',
    'sup.meta': 'steamprofiler.org runs on a server at home and is free. If it was useful and you want to help pay the power bill, there is a way.',
    'sup.no_promise': 'no promises',
    'sup.none': 'No support channel is configured. Missing from .env: {vars}.',
