    'cd.note': 'Um conjunto é uma de cada carta dele, pela oferta mais barata do Mercado da Comunidade. O mercado cota na moeda de quem está logado, e aqui ninguém está, então os valores chegam em dólar. Quando há cotação, o número entre parênteses é uma aproximação desse dólar e não um preço: cada moeda tem a sua própria fila de anúncios e o seu próprio arredondamento, e o mercado vai cobrar um pouco para um lado ou para o outro. Foils são uma segunda coleção e não entram na conta.',
