    'sup.address': 'endereço',
    'sup.btc': 'Sem intermediário e sem taxa minha. Confirme o endereço antes de mandar.',
    'sup.btc_ok': 'checksum conferido no servidor',
    'sup.copy': 'Copiar',
    'sup.eyebrow': 'apoiar',
    'sup.failed': 'Não consegui carregar os canais de apoio agora.',
    'sup.h1': 'Isto roda na minha casa.',
    'sup.honest': 'o que eu faço com isso',
    'sup.honest_1': 'Nada aqui é assinatura e não existe nível de apoiador: quem apoia e quem não apoia veem exatamente o mesmo site, com as mesmas funções. Não vou trancar nada atrás de pagamento.',
    'sup.honest_2': 'Se aparecer algum dinheiro, ele vai para a conta de luz do servidor e para um domínio que hoje sai do meu bolso. Se aparecer bastante, aí penso em tirar isso da minha casa e colocar num lugar que não caia quando falta energia no bairro.',
    'sup.honest_3': 'Prefere ajudar sem gastar? <a href="/feedback">Manda um recado</a> com um bug ou uma ideia - para mim isso vale igual.',
    'sup.kofi': 'Cartão, uma vez ou todo mês. Eles ficam com uma taxa.',
    'sup.lede': 'O site é de graça, não tem anúncio, não tem cookie, não tem rastreador e não vende nada - <a href="/privacy">a política de privacidade diz exatamente o que isso quer dizer</a>. Roda num servidor aqui em casa, com a minha luz e a minha chave da Steam. <b>Se ele te foi útil</b> e você quiser jogar um trocado, é por aqui - e se não quiser, use à vontade do mesmo jeito.',
    'sup.meta': 'O steamprofiler.org roda num servidor em casa e é de graça. Se te foi útil e você quiser ajudar a pagar a luz, tem como.',
    'sup.no_promise': 'sem promessa',
    'sup.none': 'Nenhum canal de apoio está configurado. Faltam variáveis no .env: {vars}.',
