    'close.title': 'ближе всего к ста процентам',
    'close.go': 'Прочитать топ-{n} игр',
    'close.head': '{n} игр',
    'close.hint': 'Те же три запроса, что говорят о редкости достижения, говорят и о том, какие ещё закрыты. Эта половина ответа приходила и выбрасывалась.',
    'close.note': (v) => `Из ${v.n} самых наигранных ${v.done} ${plural(v.doneRaw, ['закрыта полностью', 'закрыты полностью', 'закрыты полностью'])}. Порядок по числу оставшихся, а не по процентам: две из ста и две из пяти - это один и тот же вечер.`,
    'close.none': (v) => `Закрывать нечего: из ${v.n} самых наигранных ${v.done} ${plural(v.doneRaw, ['завершена', 'завершены', 'завершены'])}, а остальные вообще не публикуют достижений.`,
    'close.left': (v) => `${v.have} из ${v.total} · ${v.n} ${plural(v.raw, ['закрыто', 'закрыто', 'закрыто'])}`,
    'close.wall': 'самое редкое из оставшихся: {name} ({pct})',
    'close.next': 'самое частое из оставшихся: {name} ({pct})',
    /* ── Список друзей, по порядку ── */
    'board.title': 'список друзей, по порядку',
