    'board.hint': 'Один запрос на друга, поэтому это ждёт нажатия. Читается, сколько каждый наиграл и сколько у него есть, и больше ничего о них.',
    'board.note': 'Спросил {scanned} из списка, начиная с новых, с потолком в {limit}. Ответили {answered}; {priv} держат сведения об играх закрытыми, а Steam не даёт отличить это от пустой библиотеки.',
    'board.owns': '{n} игр',
