    /* ── Один год ── */
    'time.open': 'открыть {year} →',
    'yr.dropped': 'последний запуск в этом году',
    'yr.unlocked': 'открыто в этом году',
    'yr.note': 'Steam даёт одну дату на игру: когда её запускали в последний раз. Значит, игра на этой странице, если это год, когда её открывали в последний раз, а не если в этом году в неё играли. И не окончательно: запустите снова завтра, и она перейдёт в текущий год.',
    'yr.lede': 'В {year} последний раз запускали {n} игр, вместе они держат {h} часов. Тяжелее всех - {game}.',
    'yr.empty': 'В {year} ни одну игру не запускали в последний раз: каждую игру отсюда запускали снова после этого или не запускали вовсе.',
    'yr.opened': 'Этот аккаунт открыт {date}.',
