    'yr.in_game': (v) => `${v.n} ${plural(v.raw, ['достижение', 'достижения', 'достижений'])} в ${v.year}`,
    'yr.unlocks_hint': 'У достижения есть своя дата - единственное на профиле Steam, что действительно принадлежит году. Чтение стоит той же проверки, что и панель редкости, и это тот же ответ: нажмите в любом из двух мест, и второе уже оплачено.',
    'yr.unlocks_note': 'В пределах {n} самых наигранных. Игра ниже по библиотеке могла что-то открыть в {year}, куда это не дотянулось.',
