    'cd.cost': (v) => `По одной каждой карточки для ${v.n} ${plural(v.raw, ['открытого набора', 'открытых наборов', 'открытых наборов'])} с уже известной ценой: ${v.v} на рынке сегодня.`,
    'cd.cost_none': 'Ни у одного открытого набора пока нет цены. Рынок читается по несколько игр в минуту, так что это заполнится прямо на открытой странице.',
