    'cd.note': 'Набор - это по одной каждой карточки из него, по самому дешёвому лоту Торговой площадки. Площадка считает в валюте того, кто вошёл в аккаунт, а здесь не вошёл никто, поэтому суммы приходят в долларах. Если курс известен, число в скобках - это оценка того же доллара, а не цена: у каждой валюты своя очередь лотов и своё округление, и площадка запросит немного больше или немного меньше. Фольгированные карточки - вторая коллекция, и в счёт они не идут.',
