    'wish.unread': 'цены пока нет',
    'hold.note': 'Считаются только обычные карточки: именно из них собирается значок, который оценивает панель выше. Фольгированные - это вторая коллекция со своими ценами и своим значком. Дубликат не приближает к значку и считается отдельно, потому что только его и имеет смысл менять. Стоимость сборки набора - это сумма недостающих карточек, и она остаётся пустой, а не выдуманной, если хотя бы у одной из них сегодня нет продавца.',
