    'g.cts_note': 'Один счётчик, и он же - вся игра. Больше здесь ничего нет, потому что больше ничего не существует: эта страница ничего не потеряла.',
    'g.spo_kicker': 'Spec Ops: The Line  ·  {h} ч',
