    'g.spo_level': 'уровень',
    'g.spo_streak': 'лучшая серия',
    'g.spo_note': 'Steam хранит статистику только для мультиплеера этой игры - той части, которую никто не помнит, - поэтому она показана как есть: горстка матчей. Кампания - это список выше.',
