    'bt.resort': 'побед курортом',
    'note.ach_progress_only': 'Steam действительно отдаёт для этой игры блок статистики, но каждый счётчик в нём - это прогресс достижения, и большинство застывает на пороге, который открыл отслеживаемое достижение. Поэтому страница построена на самих достижениях, а не на числах, которые лишь выглядели бы итогами.',
