    'g.p_war_thunder_free': 'War Thunder \u043d\u0435 \u0431\u0435\u0440\u0451\u0442 \u0434\u0435\u043d\u0435\u0433 \u0437\u0430 \u0438\u0433\u0440\u0443. \u041e\u043d \u0431\u0435\u0440\u0451\u0442 \u0432\u0440\u0435\u043c\u0435\u043d\u0435\u043c, \u0438 \u0438\u043c\u0435\u043d\u043d\u043e \u044d\u0442\u043e\u0442 \u0441\u0447\u0451\u0442 \u0440\u0430\u0441\u043f\u0438\u0441\u044b\u0432\u0430\u043b\u043e \u0434\u0435\u0440\u0435\u0432\u043e \u0438\u0441\u0441\u043b\u0435\u0434\u043e\u0432\u0430\u043d\u0438\u0439 \u0432\u044b\u0448\u0435.',
