    'g.gap_ach_what': 'В этом профиле не получено ни одного достижения.',
    'g.gap_ach_why': 'Эта страница строится из достижений игры, а у профиля их пока нет. Остаются часы.',
    'g.gap_dota_fix': 'В Dota 2: Настройки → Опции → Дополнительно → «Открыть данные публичных матчей». После включения история появится здесь через несколько часов.',
    'g.gap_dota_what': 'Dota 2 не публикует историю матчей этого профиля.',
    'g.gap_dota_why': 'Процент побед, KDA и герои не приходят из API Valve - она отвечает ошибкой на любой матч. Они берутся из OpenDota, который видит только тех, кто включил открытые данные. Этот профиль не включил, либо у него нет матчей.',
