    'msg.lede': 'Напишите здесь. Я читаю всё. То, что я приму, станет пунктом на доске рядом, с текущим состоянием - а кто согласен, может проголосовать, чтобы я знал, что важнее. <b>Аккаунт не нужен.</b>',
    'msg.meta': 'Нашли баг, есть идея или хотите на что-то пожаловаться на steamprofiler.org? Пишите здесь. То, что я принимаю, попадает на открытую доску.',
    'msg.no_login': 'без входа',
    'msg.privacy': 'Я храню сообщение, контакт, если вы его напишете, и <b>хеш с солью</b> от вашего адреса - только чтобы считать один голос на человека и остановить поток. Сам адрес не храню, и на странице нет ни одного трекера.',
