    'note.progress_counters': 'Для этой игры Steam отдаёт только счётчики прогресса достижений. Большинство останавливается на своей цели, так что это прогресс, а не итог.',
    'note.wt_counters': 'Для War Thunder Steam отдаёт только счётчики прогресса достижений, и большинство перестаёт считать при достижении цели. Эти три её ещё не достигли.',
