    'sup.honest': 'что я с этим делаю',
    'sup.honest_1': 'Здесь нет подписки и нет уровней поддержки: те, кто платит, и те, кто нет, видят один и тот же сайт с одними и теми же возможностями. Я ничего не закрою за оплатой.',
    'sup.honest_2': 'Если деньги появятся, они уйдут на электричество для сервера и на домен, который сегодня я оплачиваю сам. Если появится много - подумаю о том, чтобы вынести это из дома туда, где оно не падает вместе со светом в квартале.',
    'sup.honest_3': 'Хотите помочь, не тратя денег? <a href="/feedback">Напишите сообщение</a> с багом или идеей - для меня это стоит столько же.',
    'sup.kofi': 'Карта, разово или каждый месяц. Они берут свою долю.',
    'sup.lede': 'Сайт бесплатный, без рекламы, без cookie, без трекеров и ничего не продаёт - <a href="/privacy">на странице приватности написано, что именно это значит</a>. Он работает на сервере здесь, дома, на моём электричестве и моём ключе Steam. <b>Если он вам пригодился</b> и хочется закинуть монетку - вот сюда. А если нет, пользуйтесь ровно так же.',
    'sup.meta': 'steamprofiler.org работает на сервере дома и бесплатен. Если он оказался полезен и вы хотите помочь с электричеством, есть способ.',
