    'nav.about': 'о сайте',
    'abt.title': 'О сайте - steamprofiler.org',
    'abt.eyebrow': 'о сайте',
    'abt.h1': 'Это сделал человек, и вот он.',
    'abt.lede': 'Меня зовут <b>Gustavo Cruz</b>. Я пишу код steamprofiler.org, плачу за машину, на которой он работает, и отвечаю, когда здесь что-то ломается. Сайт на каждой странице говорит о себе от первого лица и до сих пор ни разу не сказал, чьё это лицо.',
    'abt.why': 'зачем он существует',
    'abt.why_tag': 'одна картинка',
    'abt.why_1': 'Steam точно знает, сколько часов ушло в каждую игру, и показывает это списком, отсортированным по числу. Список - это ровно та форма, которая не отвечает на вопрос, который у людей на самом деле есть о своей библиотеке: не "что сверху", а "во что всё это сложилось".',
    'abt.why_2': 'Поэтому сайт рисует библиотеку в масштабе: один прямоугольник на игру, площадь пропорциональна часам. Тринадцать лет аккаунта становятся одной картинкой, и "сорок процентов ушло в одну игру" перестаёт быть фразой, которую надо вычислять, и становится первым, что видно на экране.',
    'abt.why_3': 'Остальное выросло отсюда. Каждая игра, которую хоть раз запускали, получает страницу, построенную из интерфейса самой игры, потому что общий шаблон превратил бы сто пятьдесят девять разных игр в одну таблицу.',
    'abt.safe': 'это безопасно',
    'abt.safe_tag': 'короткий ответ',
    'abt.safe_1': 'Это честный вопрос к любому сайту, которому нужен профиль Steam, и ответ - в том, чего этот сайт никогда не просит.',
    'abt.safe_login': '<b>Вы никогда не входите в аккаунт.</b> Здесь нет логина, нет OpenID, нет кнопки входа через Steam, и ничто здесь не может действовать от имени аккаунта. Всё на этом сайте читается из профиля, который Steam и так публикует для всех.',
    'abt.safe_key': '<b>Вы никогда не даёте мне ключ.</b> Ключ Steam API мой, он живёт на моём сервере, и именно поэтому здесь вообще есть бэкенд - ключ в браузере это отданный ключ.',
    'abt.safe_trade': '<b>Здесь ничего не меняют, не продают и не предлагают.</b> Никаких предметов, скинов, ставок, никаких "подтвердите аккаунт". Если вы найдёте на этом домене страницу, которая делает что-то из этого, она не моя.',
    'abt.safe_store': '<b>О вас ничего не сохраняется.</b> Ни аккаунта, ни куки, ни трекеров, ни профиля аналитики. То, что даёт один запрос, живёт в кеше пятнадцать минут и исчезает - <a href="/privacy">страница приватности это длинная версия</a>.',
    'abt.safe_2': 'Клиентская половина сайта открыта, лицензия MIT, и <a href="https://github.com/GustavoHSCruz/SteamProfiler.Front" rel="noopener">каждая её строка лежит на GitHub ↗</a>. Не нужно верить ничему из написанного выше на слово; это можно прочитать.',
    'abt.made': 'как он сделан',
    'abt.made_tag': 'без сборки',
    'abt.made_1': 'Статические HTML, CSS и JavaScript, без фреймворка, без сборщика и без зависимостей, перед одним небольшим сервисом на Python, который говорит со Steam. Что лежит в папке, то браузер и получает. Шрифты лежат здесь же, так что даже запрос за шрифтом не уходит на чужой сервер.',
    'abt.made_2': 'Это хобби-проект, и он сделан с помощью ИИ, проверен и выпущен мной. Я лучше скажу это прямо здесь, чем позволю кому-то выяснить это самому и гадать, что ещё не было сказано.',
    'abt.find': 'где меня найти',
    'abt.find_tag': 'и сайт',
    'abt.gh': 'GitHub · GustavoHSCruz ↗',
    'abt.repo': 'Исходный код этого сайта ↗',
    'abt.mine': 'Мой собственный профиль, прочитанный сайтом',
    'abt.say': 'Сообщить, что что-то сломалось',
    'abt.help': 'Помочь оплатить электричество',
    'abt.note': 'steamprofiler.org не связан с Valve. Он читает то, что публикует Steam, и ничего сверх того, и перестанет работать в день, когда Steam перестанет это публиковать.',
